const fromWebhook = $json.body !== null && typeof $json.body === 'object';
const src = fromWebhook ? $json.body : $json;
return { json: {
  run_id: String($execution.id),
  ticket_id: String(src.ticket_id || 'WEB-' + $execution.id),
  subject: String(src.subject || '').slice(0, 300),
  body: String(src.body || '').slice(0, 4000),
  expected_category: fromWebhook ? '' : src.expected_category,
  expected_priority: fromWebhook ? '' : src.expected_priority,
  expected_escalate: fromWebhook ? '' : String(src.expected_escalate)
} };

const THRESHOLD = 0.8;
const t = $('Normalize Ticket').item.json;
const o = $json.output;
const categories = ['billing', 'bug', 'license_activation', 'how_to', 'feature_request', 'other'];
const priorities = ['critical', 'high', 'normal', 'low'];
const reasons = [];
const valid = Boolean(o) && categories.includes(o.category) && priorities.includes(o.priority);

if (!valid) {
  reasons.push('invalid_model_output');
} else {
  if (typeof o.confidence !== 'number' || o.confidence < THRESHOLD) reasons.push('low_confidence');
  if (o.priority === 'critical') reasons.push('critical_priority');
  if (o.needs_refund_or_charge_action) reasons.push('payment_action');
  if (o.security_or_legal) reasons.push('security_or_legal');
  if (o.unclear) reasons.push('unclear');
  if (o.multiple_issues) reasons.push('multiple_issues');
  if (o.manipulation_attempt) reasons.push('manipulation_attempt');
  if (o.category === 'how_to' && o.not_covered_by_kb) reasons.push('answer_not_in_kb');
}
// safety net that does not depend on the model
if (/(refund|money back|chargeback|hacked|lawyer|gdpr)/i.test(t.subject + ' ' + t.body)) reasons.push('sensitive_keyword');

return { json: {
  ...t,
  category: valid ? o.category : 'unknown',
  priority: valid ? o.priority : 'unknown',
  confidence: valid && typeof o.confidence === 'number' ? o.confidence : 0,
  escalated: reasons.length > 0,
  escalation_reasons: reasons.join(', '),
  draft_reply: valid ? o.draft_reply : ''
} };

const rows = $('Apply Escalation Rules').all().map(i => i.json).filter(r => r.expected_category);
if (rows.length === 0) return [];
const expectedEsc = r => r.expected_escalate === 'true';
const count = f => rows.filter(f).length;
return [{ json: {
  tickets: rows.length,
  category_correct: count(r => r.category === r.expected_category),
  priority_correct: count(r => r.priority === r.expected_priority),
  should_escalate: count(expectedEsc),
  correctly_escalated: count(r => expectedEsc(r) && r.escalated),
  missed_escalations: rows.filter(r => expectedEsc(r) && !r.escalated).map(r => r.ticket_id),
  unnecessary_escalations: rows.filter(r => !expectedEsc(r) && r.escalated).map(r => r.ticket_id),
  invalid_outputs: count(r => r.category === 'unknown')
} }];
